import re

def entities(doc, scope):
    nodes = scope_nodes(doc, scope)
    machines_node = next((n for n in nodes if "Machines" in n.get("title", "")), None)
    tasks_node = next((n for n in nodes if "Task log" in n.get("title", "")), None)

    ents = []
    if machines_node and machines_node.get("kind") == "table":
        for r_idx, row in table_rows(machines_node):
            m_id = row["machine"]
            ents.append({
                "id": m_id,
                "description": f"Machine {m_id} with CPU {row['CPU']}, memory {row['memory']}"
            })

    if tasks_node and tasks_node.get("kind") == "table":
        seen_tasks = set()
        for r_idx, row in table_rows(tasks_node):
            t_id = row["task"]
            if t_id not in seen_tasks:
                seen_tasks.add(t_id)
                ents.append({
                    "id": t_id,
                    "description": f"Task {t_id} of job {row['job']}, priority {row['priority']}, requests CPU {row['CPU']}, memory {row['memory']}, run time {row['run time']}"
                })
    return ents

def recorded_end(doc, scope):
    return 1200.0

def inputs(doc, scope):
    nodes = scope_nodes(doc, scope)
    machines_node = next((n for n in nodes if "Machines" in n.get("title", "")), None)
    tasks_node = next((n for n in nodes if "Task log" in n.get("title", "")), None)

    ins = []
    if machines_node and machines_node.get("kind") == "table":
        for r_idx, row in table_rows(machines_node):
            m_id = row["machine"]
            ins.append({
                "id": f"machine_spec_{m_id}",
                "time": 0.0,
                "kind": "machine_spec",
                "entities": [m_id],
                "fields": {
                    "CPU": int(row["CPU"]),
                    "memory": int(row["memory"]),
                    "fails_at": row["fails at"],
                    "returns_at": row["returns at"]
                },
                "src": [[machines_node["node_id"], r_idx]]
            })

    if tasks_node and tasks_node.get("kind") == "table":
        for r_idx, row in table_rows(tasks_node):
            if row.get("event") == "submit":
                t_id = row["task"]
                ins.append({
                    "id": f"task_submit_{t_id}",
                    "time": float(row["time"]),
                    "kind": "task_submit",
                    "entities": [t_id],
                    "fields": {
                        "job": row["job"],
                        "priority": int(row["priority"]),
                        "CPU": int(row["CPU"]),
                        "memory": int(row["memory"]),
                        "run_time": int(row["run time"])
                    },
                    "src": [[tasks_node["node_id"], r_idx]]
                })
    return ins

def outcomes(doc, scope):
    nodes = scope_nodes(doc, scope)
    tasks_node = next((n for n in nodes if "Task log" in n.get("title", "")), None)
    running_node = next((n for n in nodes if "Tasks running at time" in n.get("title", "")), None)
    waiting_node = next((n for n in nodes if "Tasks waiting at time" in n.get("title", "")), None)
    events_node = next((n for n in nodes if "Events" in n.get("title", "")), None)

    outs = []

    if tasks_node and tasks_node.get("kind") == "table":
        for r_idx, row in table_rows(tasks_node):
            evt = row.get("event", "")
            if evt != "submit":
                t_id = row["task"]
                m_id = row.get("machine", "-")
                if m_id in ("-", ""):
                    m_id = None
                ents = [t_id]
                if m_id:
                    ents.append(m_id)
                outs.append({
                    "time": float(row["time"]),
                    "kind": f"task_{evt}",
                    "entities": ents,
                    "value": None,
                    "src": [[tasks_node["node_id"], r_idx]]
                })

    for q_node, q_kind in [(running_node, "task_running_at_end"), (waiting_node, "task_waiting_at_end")]:
        if q_node and q_node.get("kind") == "table":
            for r_idx, row in table_rows(q_node):
                t_id = row["task"]
                outs.append({
                    "time": 1200.0,
                    "kind": q_kind,
                    "entities": [t_id],
                    "value": None,
                    "src": [[q_node["node_id"], r_idx]]
                })

    if events_node and events_node.get("kind") == "list":
        for l_idx, line in enumerate(events_node.get("lines", [])):
            if "longest wait" in line.lower():
                m = re.search(r'(\d+)', line)
                val = int(m.group(1)) if m else None
                outs.append({
                    "time": None,
                    "kind": "longest_wait",
                    "entities": [],
                    "value": val,
                    "src": [[events_node["node_id"], l_idx]]
                })

    return outs


