import heapq
from collections import defaultdict

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    if horizon is None:
        horizon = recorded_end(doc, scope)
    if start is None:
        start = 0.0

    m_specs = {}
    sub_by_time = defaultdict(list)

    for inp in inputs:
        if inp["kind"] == "machine_spec":
            mid = inp["entities"][0]
            m_specs[mid] = inp["fields"]
        elif inp["kind"] == "task_submit":
            f = inp["fields"].copy()
            f["id"] = inp["entities"][0]
            f["submit_time"] = inp["time"]
            sub_by_time[inp["time"]].append(f)

    m_state = {}
    for mid in sorted(m_specs.keys()):
        ms = m_specs[mid]
        m_state[mid] = {"up": True, "running": [], "cap_cpu": ms["CPU"], "cap_mem": ms["memory"]}

    task_info = {}
    running = {}
    queue = []
    outcomes = []

    def get_free(mid):
        m = m_state[mid]
        uc = sum(task_info[t]["CPU"] for t in m["running"])
        um = sum(task_info[t]["memory"] for t in m["running"])
        return m["cap_cpu"] - uc, m["cap_mem"] - um

    def q_key(tid):
        i = task_info[tid]
        return (-i["priority"], i["submit_time"], tid)

    ev_pq = []
    for t in sub_by_time: 
        heapq.heappush(ev_pq, t)
    for mid, ms in m_specs.items():
        fa = ms["fails_at"]
        if fa != "-" and fa != "":
            try: heapq.heappush(ev_pq, float(fa))
            except: pass
        ra = ms["returns_at"]
        if ra not in ("-", "", "never"):
            try: heapq.heappush(ev_pq, float(ra))
            except: pass
    if not ev_pq: 
        heapq.heappush(ev_pq, 0)

    processed = set()
    while ev_pq:
        t = heapq.heappop(ev_pq)
        if t in processed: continue
        if horizon is not None and t > horizon: break
        processed.add(t)

        # 1. Finishes
        finished = [tid for tid, r in running.items() if r["finish"] == t]
        finished.sort()
        for tid in finished:
            mid = running[tid]["machine"]
            m_state[mid]["running"].remove(tid)
            if t > start:
                outcomes.append({"time": t, "kind": "task_finish", "entities": [tid, mid], "value": None})
            del running[tid]

        # 2. Failures
        for mid in sorted(m_specs.keys()):
            ms = m_specs[mid]
            fa = ms["fails_at"]
            if fa != "-" and fa != "" and abs(float(fa) - t) < 0.5:
                m_state[mid]["up"] = False
                for tid in list(m_state[mid]["running"]):
                    if t > start:
                        outcomes.append({"time": t, "kind": "task_fail", "entities": [tid, mid], "value": None})
                    queue.append(tid)
                    del running[tid]
                m_state[mid]["running"] = []

        # 3. Returns
        for mid in sorted(m_specs.keys()):
            ms = m_specs[mid]
            ra = ms["returns_at"]
            if ra not in ("-", "", "never") and abs(float(ra) - t) < 0.5:
                m_state[mid]["up"] = True
                m_state[mid]["running"] = []

        # 4. Submissions
        for f in sub_by_time.get(t, []):
            tid = f["id"]
            task_info[tid] = f
            queue.append(tid)

        # 5. Scheduling round
        queue.sort(key=q_key)
        reservation = None
        backfilled = []

        idx = 0
        while idx < len(queue):
            tid = queue[idx]
            info = task_info[tid]
            rc, rm = info["CPU"], info["memory"]
            started = False

            fits_any = any(m_state[m]["up"] and m_state[m]["cap_cpu"] >= rc and m_state[m]["cap_mem"] >= rm for m in m_state)

            # a. First fit
            for mid in sorted(m_state.keys()):
                m = m_state[mid]
                if not m["up"]: continue
                fc, fm = get_free(mid)
                if fc < rc or fm < rm: continue

                if reservation and mid == reservation[1]:
                    if t + info["run_time"] <= reservation[2]:
                        pass
                    else:
                        res_c = m["cap_cpu"] - task_info[reservation[0]]["CPU"] - sum(task_info[b]["CPU"] for b in backfilled)
                        res_m = m["cap_mem"] - task_info[reservation[0]]["memory"] - sum(task_info[b]["memory"] for b in backfilled)
                        if rc > res_c or rm > res_m: 
                            continue

                queue.pop(idx)
                m["running"].append(tid)
                running[tid] = {"machine": mid, "start": t, "finish": t + info["run_time"]}
                heapq.heappush(ev_pq, t + info["run_time"])
                if t > start:
                    outcomes.append({"time": t, "kind": "task_start", "entities": [tid, mid], "value": None})
                if reservation and mid == reservation[1]:
                    backfilled.append(tid)
                started = True
                break
            if started: 
                continue

            # b. Preemption
            if reservation is None and info["priority"] >= 9:
                for mid in sorted(m_state.keys()):
                    m = m_state[mid]
                    if not m["up"]: continue
                    ft = [t2 for t2 in m["running"] if task_info[t2]["priority"] <= 1]
                    ft.sort(key=lambda x: (task_info[x]["priority"], -running[x]["start"], -int(x[1:])))
                    fc, fm = get_free(mid)
                    evict = []
                    for et in ft:
                        if fc >= rc and fm >= rm: 
                            break
                        evict.append(et)
                        fc += task_info[et]["CPU"]
                        fm += task_info[et]["memory"]
                    if fc >= rc and fm >= rm:
                        for et in evict:
                            m["running"].remove(et)
                            queue.append(et)
                            del running[et]
                            if t > start:
                                outcomes.append({"time": t, "kind": "task_evict", "entities": [et, mid], "value": None})
                        queue.pop(idx)
                        m["running"].append(tid)
                        running[tid] = {"machine": mid, "start": t, "finish": t + info["run_time"]}
                        heapq.heappush(ev_pq, t + info["run_time"])
                        if t > start:
                            outcomes.append({"time": t, "kind": "task_start", "entities": [tid, mid], "value": None})
                        started = True
                        break
            if started: 
                continue

            # c. Reservation
            if reservation is None and fits_any:
                best_t = float('inf')
                best_m = None
                for mid in sorted(m_state.keys()):
                    if not m_state[mid]["up"]: continue
                    et = min((running[t2]["finish"] for t2 in m_state[mid]["running"]), default=t)
                    if et < best_t:
                        best_t = et
                        best_m = mid
                if best_m:
                    reservation = (tid, best_m, best_t)
            idx += 1

    outcomes.sort(key=lambda x: (x["time"], x["kind"], x["entities"]))
    return outcomes

