def run_sim(scope_title):
    ins = inputs(doc, scope_title)
    m_specs = {i["entities"][0]: i["fields"] for i in ins if i["kind"] == "machine_spec"}
    t_submits = [(i["entities"][0], i["time"], i["fields"]) for i in ins if i["kind"] == "task_submit"]

    machines = {mid: {"cap_cpu": fs["CPU"], "cap_mem": fs["memory"], "up": True, "running": []} 
                for mid, fs in sorted(m_specs.items())}

    queue = []
    task_info = {}
    running = {}

    sub_by_time = defaultdict(list)
    for tid, ttime, fields in t_submits:
        sub_by_time[ttime].append((tid, fields))

    fail_by_time = defaultdict(list)
    ret_by_time = defaultdict(list)
    for mid, fs in m_specs.items():
        if fs["fails_at"] not in ("-", ""):
            fail_by_time[int(fs["fails_at"])].append(mid)
        if fs["returns_at"] not in ("-", "", "never"):
            ret_by_time[int(fs["returns_at"])].append(mid)

    ev_pq = []
    for t in sub_by_time: heapq.heappush(ev_pq, t)
    for t in fail_by_time: heapq.heappush(ev_pq, t)
    for t in ret_by_time: heapq.heappush(ev_pq, t)
    if not ev_pq: heapq.heappush(ev_pq, 0)

    outcomes = []

    def get_free(mid):
        m = machines[mid]
        uc = sum(task_info[t]["cpu"] for t in m["running"])
        um = sum(task_info[t]["mem"] for t in m["running"])
        return m["cap_cpu"] - uc, m["cap_mem"] - um

    def q_key(tid):
        i = task_info[tid]
        return (-i["priority"], i["submit_time"], tid)

    processed_times = set()
    while ev_pq:
        t = heapq.heappop(ev_pq)
        if t in processed_times: continue
        if t > 1200: break
        processed_times.add(t)

        # 1. Finishes
        finished = [tid for tid, r in running.items() if r["finish"] == t]
        finished.sort()
        for tid in finished:
            mid = running[tid]["machine"]
            machines[mid]["running"].remove(tid)
            outcomes.append({"time": t, "kind": "task_finish", "entities": [tid, mid], "value": None})
            del running[tid]

