                        if fc >= rc and fm >= rm: 
                            break
                        evict.append(et)
                        fc += task_info[et]["CPU"]
                        fm += task_info[et]["memory"]
                    if fc >= rc and fm >= rm:
                        for et in evict:
                            m["running"].remove(et)
                            queue.append(et)
                            del running[et]
                            if t > start:
                                outcomes.append({"time": t, "kind": "task_evict", "entities": [et, mid], "value": None})
                        queue.pop(idx)
                        m["running"].append(tid)
                        running[tid] = {"machine": mid, "start": t, "finish": t + info["run_time"]}
                        heapq.heappush(ev_pq, t + info["run_time"])
                        if t > start:
                            outcomes.append({"time": t, "kind": "task_start", "entities": [tid, mid], "value": None})
                        started = True
                        break
            if started: 
                continue

            # c. Reservation
            if reservation is None and fits_any:
                best_t = float('inf')
                best_m = None
                for mid in sorted(m_state.keys()):
                    if not m_state[mid]["up"]: continue
                    et = min((running[t2]["finish"] for t2 in m_state[mid]["running"]), default=t)
                    if et < best_t:
                        best_t = et
                        best_m = mid
                if best_m:
                    reservation = (tid, best_m, best_t)
            idx += 1

    outcomes.sort(key=lambda x: (x["time"], x["kind"], x["entities"]))
    return outcomes
